from itertools import product

colors = [0, 1]
edges = [(i, j) for i in range(7) for j in range(i + 1, 7)]

for coloring in product(colors, repeat=len(edges)):
    valid = True
    for i in range(7):
        for j in range(i + 1, 7):
            for k in range(j + 1, 7):
                if coloring[edges.index((i, j))] == coloring[edges.index((i, k))] == coloring[edges.index((j, k))]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            break
    if valid:
        print(' '.join(map(str, coloring)))
        break
else:
    print("UNSATISFIABLE")
